export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> original receipt. Nested maps avoid separator collisions.
  private readonly receiptsByTenant = new Map<string, Map<string, Receipt>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await between lookup and insert, so concurrent calls cannot interleave here.
    let receipts = this.receiptsByTenant.get(tenant);
    if (!receipts) {
      receipts = new Map<string, Receipt>();
      this.receiptsByTenant.set(tenant, receipts);
    }
    const existing = receipts.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    receipts.set(key, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}
EOF
cat > src/service.ts <<'EOF'
import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';
export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}
  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    if (
      typeof tenant !== 'string' || tenant === '' ||
      typeof key !== 'string' || key === '' ||
      !Number.isSafeInteger(cents) || cents <= 0 ||
      !Number.isInteger(attempts) || attempts < 1 || attempts > 5
    ) throw new Error('invalid payment');
    // Obtained once; every acknowledgement attempt forwards this same receipt.
    let receipt: Receipt | undefined;
    for (let n = 1; ; n++) {
      try {
        receipt ??= await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        if (!(error instanceof Transient) || n >= attempts) throw error;
      }
    }
  }
}
EOF
