const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

const ok = { acknowledge: async () => {} };

async function main() {
  // Equal repeat returns original receipt; concurrent equal calls debit once.
  {
    const ledger = new Ledger(); const s = new PaymentService(ledger, ok);
    const rs = await Promise.all([1, 2, 3, 4, 5].map(() => s.pay('t', 'k', 50)));
    assert.equal(ledger.entries.length, 1);
    for (const r of rs) assert.deepEqual(r, { id: 1, tenant: 't', key: 'k', cents: 50 });
  }
  // Same key, different amount: conflict, no debit.
  {
    const ledger = new Ledger(); const s = new PaymentService(ledger, ok);
    await s.pay('t', 'k', 50);
    await assert.rejects(s.pay('t', 'k', 60), err => err instanceof Error && err.message === 'key conflict');
    assert.equal(ledger.entries.length, 1);
  }
  // Scoped by tenant: same key in another tenant is a new debit.
  {
    const ledger = new Ledger(); const s = new PaymentService(ledger, ok);
    await s.pay('a', 'k', 50); await s.pay('b', 'k', 60);
    assert.equal(ledger.entries.length, 2);
  }
  // Transient ack retried with the same receipt; no second debit.
  {
    const ledger = new Ledger(); const seen = [];
    let calls = 0;
    const s = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (++calls < 3) throw new Transient('x'); } });
    const r = await s.pay('t', 'k', 5, 3);
    assert.equal(calls, 3); assert.equal(ledger.entries.length, 1);
    assert.ok(seen.every(x => x === r));
  }
  // Transient from ledger.apply is retried too.
  {
    class Flaky extends Ledger {
      n = 0;
      async apply(...a) { if (this.n++ === 0) throw new Transient('apply'); return super.apply(...a); }
    }
    const ledger = new Flaky(); const s = new PaymentService(ledger, ok);
    await s.pay('t', 'k', 5);
    assert.equal(ledger.entries.length, 1);
  }
  // Exhaustion rethrows the final Transient, after exactly `attempts` tries.
  {
    const ledger = new Ledger(); let calls = 0; const last = [];
    const s = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient(`t${++calls}`); last.push(e); throw e; } });
    await assert.rejects(s.pay('t', 'k', 5, 4), e => e === last[3]);
    assert.equal(calls, 4); assert.equal(ledger.entries.length, 1);
  }
  // attempts=1 means a single try.
  {
    let calls = 0;
    const s = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw new Transient('x'); } });
    await assert.rejects(s.pay('t', 'k', 5, 1), Transient);
    assert.equal(calls, 1);
  }
  // Non-Transient errors are not retried.
  {
    let calls = 0;
    const s = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw new Error('boom'); } });
    await assert.rejects(s.pay('t', 'k', 5), /boom/);
    assert.equal(calls, 1);
  }
  // Invalid input: throws before any ledger or transport action.
  {
    let touched = 0;
    const spy = { apply: async () => { touched++; }, acknowledge: async () => { touched++; } };
    const s = new PaymentService(spy, spy);
    const bad = [
      ['', 'k', 5], ['t', '', 5], [undefined, 'k', 5], ['t', 'k', 0], ['t', 'k', -1],
      ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN], ['t', 'k', 5, 0], ['t', 'k', 5, 6],
      ['t', 'k', 5, 1.5], ['t', 'k', 5, '2'], ['t', 'k', 5, null],
    ];
    for (const args of bad) await assert.rejects(s.pay(...args), /^Error: invalid payment$/);
    assert.equal(touched, 0);
  }
  // attempts boundaries 1 and 5 are accepted.
  {
    const s = new PaymentService(new Ledger(), ok);
    await s.pay('t', 'k', 5, 1); await s.pay('t', 'k2', 5, 5);
  }
  console.log('idempotency checks passed');
}
module.exports = main();
EOF
